from langflow.custom import Component
from langflow.io import Output
from langflow.schema.message import Message  # <-- 1. Importamos la clase Message
import os

class LectorPromptExterno(Component):
    display_name = "Lector de Prompt"
    description = "Lee el System Prompt desde un archivo .md externo y lo formatea como Mensaje."
    icon = "file-text"

    outputs = [
        # 2. Aseguramos que la interfaz sepa que sale un Message
        Output(display_name="Texto del Prompt", name="prompt_text", method="leer_archivo")
    ]

    def leer_archivo(self) -> Message: # 3. Indicamos el tipo de retorno
        ruta_archivo = 'prompt_paquita.md'
        
        try:
            with open(ruta_archivo, 'r', encoding='utf-8') as archivo:
                contenido = archivo.read()
            
            # 4. Empaquetamos el texto dentro del objeto Message
            return Message(text=contenido) 
            
        except FileNotFoundError:
            return Message(text="ERROR CRÍTICO: No se ha encontrado el archivo prompt_paquita.md en el contenedor.")
        except Exception as e:
            return Message(text=f"Error al leer el prompt: {str(e)}")

from langflow.custom import Component
from langflow.io import Output
from langchain.tools import StructuredTool
from langflow.field_typing import Tool
import requests

class GestorTareasGoogleListas(Component):
    display_name = "Google Tasks (Multilista)"
    description = "Crea tareas en listas específicas según la prioridad."
    icon = "check-square"

    outputs = [
        Output(display_name="Tool", name="tool", method="build_tool")
    ]

    def build_tool(self) -> Tool:
        
        def crear_tarea_google(titulo: str, lista: str, notas: str = "") -> str:
            """
            Crea una tarea en una lista específica.
            'titulo': Nombre de la tarea.
            'lista': Nombre de la lista (ej: 'LOGÍSTICA', 'CITAS', 'URGENTE').
            'notas': Detalles adicionales.
            """
            
            url_webhook = "https://script.google.com/macros/s/TU_WEBHOOK_TAREAS/exec"
            
            payload = {
                "titulo": titulo,
                "lista": lista.upper(), # Lo enviamos en mayúsculas para consistencia
                "notas": notas
            }
            
            try:
                response = requests.post(url_webhook, json=payload)
                return response.text
            except Exception as e:
                return f"Error al conectar con el Webhook: {str(e)}"

        return StructuredTool.from_function(
            func=crear_tarea_google,
            name="crear_tarea_google",
            description="Crea tareas organizadas por listas. Obligatorio especificar la 'lista'."
        )

from langflow.custom import Component
from langflow.io import Output
from langchain.tools import StructuredTool
from langflow.field_typing import Tool
import requests

class GestorTelegramPaquita(Component):
    display_name = "Publicar en Telegram"
    description = "Envía ofertas o artículos al canal oficial de Telegram."
    icon = "send" # Iconito de avión de papel

    outputs = [
        Output(display_name="Tool", name="tool", method="build_tool")
    ]

    def build_tool(self) -> Tool:
        
        def enviar_mensaje_telegram(mensaje: str) -> str:
            """
            Publica un mensaje redactado por la IA en el canal de Telegram.
            """
            BOT_TOKEN = "TU_TELEGRAM_BOT_TOKEN" 
            CHAT_ID = "@TU_CANAL"
            
            # URL de la API oficial de Telegram
            url = f"https://api.telegram.org/bot{BOT_TOKEN}/sendMessage"
            
            payload = {
                "chat_id": CHAT_ID,
                "text": mensaje,
                "parse_mode": "HTML" # Permite que el bot use negritas (<b>) si quiere
            }
            
            try:
                # Enviamos la petición
                respuesta = requests.post(url, json=payload)
                data = respuesta.json()
                
                if data.get("ok"):
                    return f"ÉXITO: Mensaje publicado en Telegram. ID del mensaje: {data['result']['message_id']}"
                else:
                    return f"ERROR de Telegram: {data.get('description')}"
                    
            except Exception as e:
                return f"Error de conexión: {str(e)}"

        return StructuredTool.from_function(
            func=enviar_mensaje_telegram,
            name="enviar_mensaje_telegram",
            description="Utiliza esta herramienta para publicar anuncios, ofertas o noticias en el canal de Telegram."
        )

