                    return f"ERROR de Mastodon: {response.text}"
            except Exception as e:
                return f"Error de conexión: {str(e)}"

        return StructuredTool.from_function(
            func=publicar_mastodon,
            name="publicar_mastodon",
            description="Utiliza esta herramienta para publicar contenido, fotos o actualizaciones en Mastodon."
