from langflow.custom import Component
from langflow.io import Output
from langchain.tools import StructuredTool
from langflow.field_typing import Tool
import requests
import re

class GestorMastodonLeer(Component):
    display_name = "Mastodon (Leer Menciones)"
    description = "Obtiene las últimas menciones reales para moderar y clasificar."
    icon = "message-square"

    outputs = [
        Output(display_name="Tool", name="tool", method="build_tool")
    ]

    def build_tool(self) -> Tool:
        
        def leer_menciones_mastodon() -> str:
            """
            Obtiene las últimas 5 menciones (comentarios) de la cuenta de Mastodon.
            """
            ACCESS_TOKEN = "TU_MASTODON_ACCESS_TOKEN"
            URL_BASE = "https://mastodon.social/api/v1/notifications?types[]=mention&limit=5"
            
            headers = {
                "Authorization": f"Bearer {ACCESS_TOKEN}"
            }
            
            try:
                response = requests.get(URL_BASE, headers=headers)
                if response.status_code == 200:
                    notificaciones = response.json()
                    if not notificaciones:
                        return "No hay menciones nuevas."
                    
                    resultado = "Nuevas menciones detectadas en Mastodon:\n"
                    for notif in notificaciones:
                        usuario = notif['account']['acct']
                        # Mastodon devuelve HTML, lo limpiamos rápido
                        contenido_html = notif['status']['content']
                        contenido_limpio = re.sub('<[^<]+?>', '', contenido_html) 
                        
                        resultado += f"- Usuario @{usuario}: '{contenido_limpio}'\n"
                    
                    return resultado
                else:
                    return f"ERROR de Mastodon: {response.text}"
            except Exception as e:
                return f"Error de conexión: {str(e)}"

        return StructuredTool.from_function(
            func=leer_menciones_mastodon,
            name="leer_menciones_mastodon",
            description="Llama a esta herramienta sin parámetros para obtener las menciones recientes que requieren clasificación."
        )

