import requests

class GestorMastodonProgramar(Component):
    display_name = "Mastodon (Programar Post)"
    description = "Programa la publicación de un estado (Toot) para una fecha y hora futuras."
    icon = "clock"

    outputs = [
        Output(display_name="Tool", name="tool", method="build_tool")
    ]

    def build_tool(self) -> Tool:
        
        def programar_post_mastodon(texto: str, fecha_hora_iso: str) -> str:
            """
            Programa un post en Mastodon para el futuro.
            'texto': El contenido del post con emojis y hashtags.
            'fecha_hora_iso': Fecha y hora en formato ISO 8601 (Ej: 2026-06-02T09:00:00Z). Debe ser al menos 5 minutos en el futuro.
            """
            # --- CONFIGURACIÓN ---
            ACCESS_TOKEN = "TU_MASTODON_ACCESS_TOKEN"
            URL_BASE = "https://mastodon.social/api/v1/statuses" 
            
            headers = {
                "Authorization": f"Bearer {ACCESS_TOKEN}"
            }
            payload = {
                "status": texto,
                "scheduled_at": fecha_hora_iso,
                "visibility": "public"
            }
            
            try:
                response = requests.post(URL_BASE, headers=headers, data=payload)
                if response.status_code == 200:
                    data = response.json()
                    if "scheduled_at" in data:
                        return f"¡ÉXITO! Post programado correctamente para: {data['scheduled_at']}. ID de programación: {data['id']}"
                    return f"¡ÉXITO! Procesado. Respuesta del servidor: {response.text}"
                else:
                    return f"ERROR de Mastodon: {response.text}"
            except Exception as e:
                return f"Error de conexión: {str(e)}"

        return StructuredTool.from_function(
            func=programar_post_mastodon,
            name="programar_post_mastodon",
            description="Programa mensajes o anuncios recurrentes de la agenda para que se publiquen automáticamente más tarde."
        )

