class GestorMastodonSocialListening(Component):
    display_name = "Mastodon (Social Listening)"
    description = "Busca publicaciones en la red por hashtags o palabras clave para detectar oportunidades."
    icon = "search"

    outputs = [
        Output(display_name="Tool", name="tool", method="build_tool")
    ]

    def build_tool(self) -> Tool:
        
        def buscar_tendencias_mastodon(termino_busqueda: str) -> str:
            """
            Busca posts públicos en Mastodon que contengan un hashtag o palabra clave.
            'termino_busqueda': El término, hashtag o palabra clave a buscar (Ej: 'piercing' o 'joyería').
            """
            # --- CONFIGURACIÓN ---
            ACCESS_TOKEN = "TU_MASTODON_ACCESS_TOKEN"
            # Limitamos a los 3 resultados más recientes para no saturar el contexto de la IA
            URL_BASE = f"https://mastodon.social/api/v2/search?q={termino_busqueda}&type=statuses&limit=3"
            
            headers = {
                "Authorization": f"Bearer {ACCESS_TOKEN}"
            }
            
            try:
                response = requests.get(URL_BASE, headers=headers)
                if response.status_code == 200:
                    data = response.json()
                    statuses = data.get("statuses", [])
                    
                    if not statuses:
                        return f"No se encontraron posts públicos recientes con el término: '{termino_busqueda}'."
                    
                    resultado = f"Resultados de Social Listening para '{termino_busqueda}':\n"
                    for post in statuses:
                        usuario = post['account']['acct']
                        contenido_html = post['content']
                        contenido_limpio = re.sub('<[^<]+?>', '', contenido_html)
                        url_post = post['url']
                        
                        resultado += f"- De @{usuario}: '{contenido_limpio}' (URL: {url_post})\n"
                    return resultado
                else:
                    return f"ERROR de Mastodon: {response.text}"
            except Exception as e:
                return f"Error de conexión: {str(e)}"

        return StructuredTool.from_function(
            func=buscar_tendencias_mastodon,
            name="buscar_tendencias_mastodon",
            description="Busca conversaciones públicas en la red sobre un tema clave para interactuar proactivamente."
        )
